function label(e){return e.type==='feed'?'Feed':e.type==='sleep'?'Sleep':e.type==='diaper'?'Diaper':e.type==='medication'?'Medication':e.type==='temperature'?'Temperature':'Note'}
function supplyFeelText(value){return ['Not recorded','Low','Below average','Average','Good','High'][Number(value)||0]||'Not recorded'}
const OBSERVATION_LABELS={fellAsleep:'Fell asleep during feed',latchedWell:'Latched well',neededLatchHelp:'Needed help to latch',calm:'Calm and settled',burpedWell:'Burped well',spitUp:'Spit up',stillHungry:'Still seemed hungry'};
const NOTE_OBSERVATION_LABELS={eyesOpen:'Eyes open',wokeUp:'Woke up',cried:'Cried',alert:'Alert',sleepy:'Sleepy',fussy:'Fussy',calm:'Calm and settled',hungerCues:'Showing hunger cues',hiccups:'Hiccups',sneezed:'Sneezed',spitUp:'Spit up',skinToSkin:'Skin-to-skin'};
const MUM_OBSERVATION_LABELS={mumCalm:'Calm',mumContent:'Content',mumTired:'Tired',mumWorried:'Worried',mumOverwhelmed:'Overwhelmed',mumTearful:'Tearful',mumLow:'Low mood',mumIrritable:'Irritable',mumSupported:'Feeling supported',mumNeedsSupport:'Needs some support'};
function observationText(value){if(MUM_OBSERVATION_LABELS[value])return `Mum: ${MUM_OBSERVATION_LABELS[value]}`;return OBSERVATION_LABELS[value]||NOTE_OBSERVATION_LABELS[value]||value}
function observationSummary(e){let items=Array.isArray(e.observations)?e.observations:[];if(!items.length)return '';let visible=items.slice(0,2).map(observationText).join(' · ');return ` · ${visible}${items.length>2?' +'+(items.length-2):''}`}
function meta(e){if(e.type==='feed')return `${feedMethodLabel(e)}${(e.method==='Breast'||e.method==='Pumping')&&e.side?' · '+e.side:''}${e.amount?' · '+e.amount+' '+(e.amountUnit||'ml'):''}${e.duration?' · '+e.duration+' min':''}${e.method==='Pumping'&&e.supplyFeel?' · felt '+supplyFeelText(e.supplyFeel).toLowerCase():''}${observationSummary(e)}`;if(e.type==='sleep')return `${e.duration||0} minutes`;if(e.type==='diaper')return (e.kind||'wet').replace(/^./,x=>x.toUpperCase());if(e.type==='medication')return `${e.medication||'Medication'}${e.dose?' · '+e.dose+' '+(e.doseUnit||''):''}`;if(e.type==='temperature')return `${e.temperature||'—'} ${e.temperatureUnit||'°C'}`;if(e.type==='note'){let observations=(e.observations||[]).map(observationText);return observations.length?observations.join(' · '):'Remembered moment'}return 'Remembered moment'}
function fields(type,entry=null){if(type==='feed'){return `<div class="feed-form-grid"><label>Method<select id="fieldMethod"><option value="Breast">Breast</option><option value="CupFormula">Cup with formula</option><option value="CupBreast">Cup with breast milk</option><option value="Pumping">Pumping</option><option value="Syringe">Syringe</option><option value="Mixed">Mixed</option></select></label><label id="breastSideField">Side<select id="fieldSide"><option>Left</option><option>Right</option><option>Both</option></select></label></div><label class="amount-label">Amount <span>optional</span><div class="amount-row"><input id="fieldAmount" type="number" min="0" step="0.5" inputmode="decimal" placeholder="0"><select id="fieldAmountUnit" aria-label="Amount unit"><option value="ml">ml</option><option value="oz">oz</option></select></div><div class="amount-slider-row"><input id="fieldAmountSlider" type="range" min="0" max="150" step="5" value="0" aria-label="Feed amount"><output id="fieldAmountOutput">Not set</output></div></label><div id="supplyFeelField" class="supply-feel-field" hidden><label for="fieldSupplyFeel">How did milk supply feel? <span id="fieldSupplyFeelLabel">Not recorded</span></label><input id="fieldSupplyFeel" type="range" min="0" max="5" step="1" value="0" aria-label="Subjective milk supply feel"><div class="range-labels"><span>Low</span><span>High</span></div><small>Subjective note only</small></div><details class="feed-observations"><summary>Quick observations <span>optional</span></summary><div class="observation-chips">${Object.entries(OBSERVATION_LABELS).map(([value,text])=>`<label class="observation-chip"><input type="checkbox" value="${value}" data-observation><span>${text}</span></label>`).join('')}</div></details><div class="feed-duration-row"><label>Duration <span>optional</span><input id="fieldDuration" type="number" min="1" placeholder="Minutes"></label><button type="button" id="startTimer" class="timer-button">Start timer</button></div>`}if(type==='sleep')return '<label>Duration (minutes)<input id="fieldDuration" type="number" min="1" placeholder="e.g. 45"></label><button type="button" id="startTimer" class="timer-button">Start sleep timer</button>';if(type==='diaper')return '<label>Type<select id="fieldKind"><option value="wet">Wet</option><option value="dirty">Dirty</option><option value="both">Wet + dirty</option></select></label>';if(type==='medication')return '<label>Medication<input id="fieldMedication" type="text" placeholder="e.g. vitamin D"></label><label>Dose (optional)<div class="amount-row"><input id="fieldDose" type="number" min="0" step="0.1" placeholder="Dose"><input id="fieldDoseUnit" type="text" value="ml" aria-label="Dose unit"></div></label>';if(type==='temperature')return '<label>Temperature<input id="fieldTemperature" type="number" min="30" max="45" step="0.1" placeholder="e.g. 37.2"></label><label>Unit<select id="fieldTemperatureUnit"><option value="°C">°C</option><option value="°F">°F</option></select></label>';if(type==='note')return `<details class="feed-observations note-observations" open><summary>Baby observations <span>choose any that apply</span></summary><div class="observation-chips">${Object.entries(NOTE_OBSERVATION_LABELS).map(([value,text])=>`<label class="observation-chip"><input type="checkbox" value="${value}" data-observation><span>${text}</span></label>`).join('')}</div></details><details class="feed-observations note-observations" open><summary>Mum check-in <span>how are you feeling?</span></summary><div class="observation-chips">${Object.entries(MUM_OBSERVATION_LABELS).map(([value,text])=>`<label class="observation-chip mum-observation"><input type="checkbox" value="${value}" data-observation><span>${text}</span></label>`).join('')}</div></details>`;return '<p class="subtle" style="margin-top:14px">Capture a sweet moment, a question, or anything you want to remember.</p>'}
function bindAmountSlider(){let input=$('#fieldAmount'),unit=$('#fieldAmountUnit'),slider=$('#fieldAmountSlider'),output=$('#fieldAmountOutput');if(!input||!unit||!slider||!output)return;let configure=()=>{let ounces=unit.value==='oz';slider.max=ounces?'5':'150';slider.step=ounces?'0.5':'5';let value=Math.max(0,Number(input.value)||0);slider.value=Math.min(Number(slider.max),value);output.textContent=value?`${value} ${unit.value}`:'Not set'};slider.oninput=()=>{input.value=Number(slider.value)||'';configure()};input.oninput=configure;unit.onchange=configure;configure()}
function bindSupplyFeel(){let method=$('#fieldMethod'),field=$('#supplyFeelField'),input=$('#fieldSupplyFeel'),label=$('#fieldSupplyFeelLabel');if(!method||!field||!input||!label)return;let update=()=>{field.hidden=method.value!=='Pumping';label.textContent=supplyFeelText(input.value)};method.addEventListener('change',update);input.addEventListener('input',update);update()}
function bindObservationChips(){let panel=document.querySelector('.feed-observations');if(panel&&observationSelection.length)panel.open=true;document.querySelectorAll('[data-observation]').forEach(input=>{input.checked=observationSelection.includes(input.value);input.onchange=()=>{observationSelection=[...document.querySelectorAll('[data-observation]:checked')].map(item=>item.value)}})}
function bindFeedMethod(){bindObservationChips();let method=$('#fieldMethod'),side=$('#breastSideField');if(!method||!side)return;let update=()=>{side.hidden=!['Breast','Pumping'].includes(method.value)};method.onchange=update;update();bindAmountSlider();bindSupplyFeel()}
